def m(r):
    c_v = r["buy"] + r["dl"] + r["extra"]; nu = r["nu"]
    if r["vat"] == "без":  # НМЦ без НДС и сравнение без НДС
        bid = nu * .9; usn = (bid - c_v) / bid; osno = (bid - c_v / 1.22) / bid; rev_u = bid
        usn_w = usn
    else:
        bid_v = nu * .9; bid_nv = bid_v / 1.22
        usn = (bid_v - c_v) / bid_v; usn_w = (bid_nv - c_v) / bid_nv; osno = (bid_nv - c_v / 1.22) / bid_nv; rev_u = bid_v
        if r["ev"] == "без": usn = usn_w
    return dict(cost=c_v, usn=usn, usn_w=usn_w, osno=osno, p=usn * rev_u * r["q"], rev=nu * .9 * r["q"])
